eventScripts.script:
if currentValue.value == 1 and previousValue.value != 1:

    carrierValue = system.tag.readBlocking(
        ["[default]BACC_VCL6/Stations/EM30/Carrier_RFID"]
    )[0].value

    system.tag.writeBlocking(
        ["[default]BACC_VCL6/Stations/EM30/EM30_CarrierFault"],
        [carrierValue]
    )
